def translate(key: str, language: str = DEFAULT_LANGUAGE, **values: object) -> str:
    """Return a translated UI string, falling back safely to Spanish."""
    language_catalog = _TRANSLATIONS.get(language, _TRANSLATIONS[DEFAULT_LANGUAGE])
    text = language_catalog.get(key, _TRANSLATIONS[DEFAULT_LANGUAGE].get(key, key))
    # Reemplaza {name} y {name:spec} (p. ej. {minutes:02d}, {percent:.0f});
    # las demás llaves del texto (CSS/HTML) se dejan intactas.
    for name, value in values.items():
        text = re.sub(
            r"\{" + re.escape(name) + r"(?::([^{}]*))?\}",
            lambda match, value=value: format(value, match.group(1) or ""),
            text,
        )
    return text


def get_language() -> str:
    """Read the selected language from Streamlit session state."""
    import streamlit as st

    language = st.session_state.get("language", DEFAULT_LANGUAGE)
    return language if language in SUPPORTED_LANGUAGES else DEFAULT_LANGUAGE


def t(key: str, **values: object) -> str:
    """Translate a key using the language selected for the current session."""
    return translate(key, get_language(), **values)


def t_list(key: str) -> list[str]:
    """Return a localized list used by repeated guide markup."""
    catalog = _TRANSLATIONS.get(get_language(), _TRANSLATIONS[DEFAULT_LANGUAGE])
    value = catalog.get(key, _TRANSLATIONS[DEFAULT_LANGUAGE].get(key, []))
    return value if isinstance(value, list) else [str(value)]